<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { approveReturn, cancelAdminOrder, completeRefund, getAdminOrders, rejectReturn, shipOrder } from '@/api/adminOrders'
import { orderStatusOptions, orderStatuses, type AdminOrder } from '@/types/order'
import { errorMessage } from '@/utils/errors'

const orders = ref<AdminOrder[]>([]); const totalCount = ref(0); const loading = ref(false); const submittingId = ref<number | null>(null); const error = ref(''); const message = ref(''); const expandedId = ref<number | null>(null); const notes = reactive<Record<number, string>>({})
const query = reactive({ keyword: '', status: '', createdFrom: '', createdTo: '', sortBy: 'createdAt' as const, sortDirection: 'desc' as const, page: 1, pageSize: 20 })
const pageCount = computed(() => Math.max(1, Math.ceil(totalCount.value / query.pageSize)))

async function load(): Promise<void> {
  if (query.createdFrom && query.createdTo && query.createdFrom > query.createdTo) { error.value = '建立迄日不得早於建立起日。'; return }
  loading.value = true; error.value = ''; try { const result = await getAdminOrders({ keyword: query.keyword || undefined, status: query.status || undefined, createdFrom: query.createdFrom || undefined, createdTo: query.createdTo ? `${query.createdTo}T23:59:59` : undefined, sortBy: query.sortBy, sortDirection: query.sortDirection, page: query.page, pageSize: query.pageSize }); orders.value = result.items; totalCount.value = result.totalCount } catch (reason) { error.value = errorMessage(reason) } finally { loading.value = false }
}
async function search(): Promise<void> { query.page = 1; await load() }
async function clearSearch(): Promise<void> { Object.assign(query, { keyword: '', status: '', createdFrom: '', createdTo: '', sortBy: 'createdAt', sortDirection: 'desc', page: 1 }); await load() }
async function changePage(page: number): Promise<void> { query.page = Math.min(Math.max(page, 1), pageCount.value); await load() }
async function execute(order: AdminOrder, operation: () => Promise<unknown>, successMessage: string): Promise<void> { if (submittingId.value !== null) return; submittingId.value = order.id; error.value = ''; message.value = ''; try { await operation(); message.value = successMessage; await load() } catch (reason) { error.value = errorMessage(reason) } finally { submittingId.value = null } }
async function ship(order: AdminOrder): Promise<void> { await execute(order, () => shipOrder(order.id), `訂單 #${order.id} 已標記為寄送中。`) }
async function cancel(order: AdminOrder): Promise<void> { if (!confirm(`確定取消訂單 #${order.id}？取消後商品庫存將回補。`)) return; await execute(order, () => cancelAdminOrder(order.id), `訂單 #${order.id} 已取消。`) }
async function approve(order: AdminOrder): Promise<void> { await execute(order, () => approveReturn(order.id, notes[order.id]), `訂單 #${order.id} 的退貨申請已核准。`) }
async function reject(order: AdminOrder): Promise<void> { await execute(order, () => rejectReturn(order.id, notes[order.id]), `訂單 #${order.id} 的退貨申請已駁回。`) }
async function refund(order: AdminOrder): Promise<void> { if (!confirm(`確認已人工退款 NT$ ${order.totalAmount.toLocaleString()}？`)) return; await execute(order, () => completeRefund(order.id, notes[order.id]), `訂單 #${order.id} 已記錄人工退款完成。`) }
onMounted(load)
</script>

<template><section><div class="page-header"><h1>訂單管理</h1><RouterLink class="button secondary" to="/admin">管理首頁</RouterLink></div><p v-if="error" class="alert">{{ error }}</p><p v-if="message" class="alert success">{{ message }}</p>
  <form class="card form-grid" @submit.prevent="search"><div class="search-grid"><label class="form-row">關鍵字<input v-model.trim="query.keyword" placeholder="訂單編號、會員、Email 或商品" /></label><label class="form-row">狀態<select v-model="query.status"><option value="">全部</option><option v-for="status in orderStatusOptions" :key="status.value" :value="status.value">{{ status.label }}</option></select></label><label class="form-row">建立起日<input v-model="query.createdFrom" type="date" /></label><label class="form-row">建立迄日<input v-model="query.createdTo" type="date" /></label><label class="form-row">排序<select v-model="query.sortBy"><option value="createdAt">建立時間</option><option value="totalAmount">訂單金額</option></select></label><label class="form-row">方向<select v-model="query.sortDirection"><option value="desc">降冪</option><option value="asc">升冪</option></select></label></div><div class="actions"><button class="button" :disabled="loading">搜尋</button><button class="button secondary" type="button" :disabled="loading" @click="clearSearch">清除</button></div></form>
  <p v-if="loading">載入中...</p><div v-else class="order-list"><article v-for="order in orders" :key="order.id" class="card"><div class="page-header"><div><h2>訂單 #{{ order.id }}</h2><p class="muted">{{ order.account }}／{{ order.displayName || '-' }}／{{ order.email || '-' }}</p><p>{{ new Date(order.createdAt).toLocaleString() }} · <strong>{{ order.statusName }}</strong></p></div><div><strong>NT$ {{ order.totalAmount.toLocaleString() }}</strong></div></div>
    <div class="actions"><button class="button secondary" @click="expandedId = expandedId === order.id ? null : order.id">{{ expandedId === order.id ? '收合明細' : '查看明細' }}</button><button v-if="order.status === orderStatuses.pending" class="button" :disabled="submittingId !== null" @click="ship(order)">標記寄送中</button><button v-if="order.status === orderStatuses.pending" class="button danger" :disabled="submittingId !== null" @click="cancel(order)">取消訂單</button></div>
    <div v-if="expandedId === order.id" class="details"><div class="table-wrap"><table><thead><tr><th>商品</th><th>單價</th><th>數量</th><th>小計</th></tr></thead><tbody><tr v-for="item in order.items" :key="item.productCode"><td>{{ item.productName }}（{{ item.productCode }}）</td><td>NT$ {{ item.unitPrice.toLocaleString() }}</td><td>{{ item.quantity }}</td><td>NT$ {{ item.subtotal.toLocaleString() }}</td></tr></tbody></table></div><p v-if="order.returnReason"><strong>退貨原因：</strong>{{ order.returnReason }}</p><p v-if="order.returnReviewNote"><strong>審核備註：</strong>{{ order.returnReviewNote }}</p><p v-if="order.refundCompletedAt"><strong>退款完成：</strong>{{ new Date(order.refundCompletedAt).toLocaleString() }}，NT$ {{ (order.refundAmount ?? 0).toLocaleString() }}</p>
      <div v-if="order.status === orderStatuses.returnRequested || order.status === orderStatuses.returnApproved" class="review-box"><label class="form-row">處理備註<textarea v-model.trim="notes[order.id]" maxlength="500" rows="3" /></label><div class="actions"><button v-if="order.status === orderStatuses.returnRequested" class="button" :disabled="submittingId !== null" @click="approve(order)">核准退貨</button><button v-if="order.status === orderStatuses.returnRequested" class="button danger" :disabled="submittingId !== null" @click="reject(order)">駁回退貨</button><button v-if="order.status === orderStatuses.returnApproved" class="button danger" :disabled="submittingId !== null" @click="refund(order)">完成人工退款</button></div></div>
    </div></article><div v-if="!orders.length" class="card">目前沒有符合條件的訂單。</div></div>
  <nav v-if="totalCount" class="actions pagination"><button class="button secondary" :disabled="query.page <= 1 || loading" @click="changePage(query.page - 1)">上一頁</button><span>第 {{ query.page }} / {{ pageCount }} 頁，共 {{ totalCount }} 筆</span><button class="button secondary" :disabled="query.page >= pageCount || loading" @click="changePage(query.page + 1)">下一頁</button></nav>
</section></template>

<style scoped>.search-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:16px}.order-list{display:grid;gap:20px;margin-top:24px}.details,.review-box{margin-top:20px}.review-box textarea{width:100%;padding:10px 12px;border:1px solid #cbd2da;border-radius:8px}.pagination{justify-content:center;margin-top:20px}</style>